inputs = ['xgkuyu', 'yy', 'yi', 'dbe', 'auigvb']
outputs = ['xeuuyu', 'yy', 'yi', 'dae', 'auigva']

print("Careful analysis of all pairs:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\nPair {i+1}: '{inp}' -> '{outp}'")

    # Find all character differences
    min_len = min(len(inp), len(outp))
    changes = []
    for j in range(min_len):
        if inp[j] != outp[j]:
            changes.append((j, inp[j], outp[j]))

    if len(inp) != len(outp):
        print(f"  Length change: {len(inp)} -> {len(outp)}")

    if changes:
        for pos, from_char, to_char in changes:
            print(f"  Position {pos}: '{from_char}' -> '{to_char}'")
    else:
        print("  No character changes")

print("\nLooking for common transformations across all pairs:")
# Let's see what transformations are consistently needed
transformations = {}

for inp, outp in zip(inputs, outputs):
    min_len = min(len(inp), len(outp))
    for j in range(min_len):
        if inp[j] != outp[j]:
            char_from = inp[j]
            char_to = outp[j]
            if char_from not in transformations:
                transformations[char_from] = char_to
            elif transformations[char_from] != char_to:
                print(f"Conflict: {char_from} maps to both {transformations[char_from]} and {char_to}")

print(f"\nAll transformations found: {transformations}")

